INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'friendship', 'n.', '/ˈfrendʃɪp/', '友谊;友情', 'A true friendship can last for a whole lifetime.', '真正的友谊能持续一生。', 'Cherishing Friendship', 1, 0, 'senior', 'wordlist', 'elective3', 'U2', 'a true friendship', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'cherish', 'v.', '/ˈtʃerɪʃ/', '珍视;珍爱;铭记', 'We should cherish the friends who stand by us.', '我们应该珍视那些支持我们的朋友。', 'Cherishing Friendship', 2, 0, 'senior', 'wordlist', 'elective3', 'U2', 'cherish a friendship', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'grateful', 'adj.', '/ˈɡreɪtfl/', '感激的;感谢的', 'Kyle gave me a grateful smile after I helped him.', '我帮了凯尔之后,他向我露出感激的微笑。', 'Cherishing Friendship', 3, 0, 'senior', 'wordlist', 'elective3', 'U2', 'a grateful smile', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'gratitude', 'n.', '/ˈɡrætɪtjuːd/', '感激;感恩', 'He finally got the chance to express his gratitude to his best friend.', '他终于有机会向最好的朋友表达感激之情。', 'Cherishing Friendship', 4, 0, 'senior', 'wordlist', 'elective3', 'U2', 'express gratitude', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'gesture', 'n.', '/ˈdʒestʃə(r)/', '举动;姿态;手势', 'With one small gesture you can change a person''s life.', '一个小小的举动就能改变一个人的一生。', 'Cherishing Friendship', 5, 0, 'senior', 'wordlist', 'elective3', 'U2', 'a small gesture', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'muscle', 'n.', '/ˈmʌsl/', '肌肉;体力', 'You will build some serious muscle carrying that pile of books every day.', '每天搬那堆书,你会练出不少肌肉。', 'Cherishing Friendship', 6, 0, 'senior', 'wordlist', 'elective3', 'U2', 'build muscle', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'graduation', 'n.', '/ˌɡrædʒuˈeɪʃn/', '毕业;毕业典礼', 'On graduation day, Kyle was chosen to give the speech.', '毕业那天,凯尔被选中致辞。', 'Cherishing Friendship', 7, 0, 'senior', 'wordlist', 'elective3', 'U2', 'graduation day', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'ceremony', 'n.', '/ˈserəməni/', '典礼;仪式', 'He spoke about friendship at the graduation ceremony.', '他在毕业典礼上谈到了友谊。', 'Cherishing Friendship', 8, 0, 'senior', 'wordlist', 'elective3', 'U2', 'the graduation ceremony', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'speech', 'n.', '/spiːtʃ/', '演讲;讲话', 'Kyle was nervous about his speech in front of the whole school.', '在全校面前演讲,凯尔很紧张。', 'Cherishing Friendship', 9, 0, 'senior', 'wordlist', 'elective3', 'U2', 'give a speech', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'nervous', 'adj.', '/ˈnɜːvəs/', '紧张的;不安的', 'My friend looked nervous, so I patted him on the back.', '我朋友看起来很紧张,于是我拍了拍他的背。', 'Cherishing Friendship', 10, 0, 'senior', 'wordlist', 'elective3', 'U2', 'feel nervous', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'pat', 'v.', '/pæt/', '轻拍;拍打', 'I patted him on the back and said he would be great.', '我拍拍他的背,说他会表现得很棒。', 'Cherishing Friendship', 11, 0, 'senior', 'wordlist', 'elective3', 'U2', 'pat on the back', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'sibling', 'n.', '/ˈsɪblɪŋ/', '兄弟姐妹', 'You should thank your parents, your teachers and your siblings.', '你应该感谢父母、老师和兄弟姐妹。', 'Cherishing Friendship', 12, 0, 'senior', 'wordlist', 'elective3', 'U2', 'your siblings', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'disbelief', 'n.', '/ˌdɪsbɪˈliːf/', '不相信;怀疑', 'I looked at my friend in disbelief as he told the story.', '他讲那个故事时,我难以置信地看着我的朋友。', 'Cherishing Friendship', 13, 0, 'senior', 'wordlist', 'elective3', 'U2', 'in disbelief', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'gasp', 'n./v.', '/ɡɑːsp/', '倒抽气;喘息', 'I heard a gasp go through the crowd at his words.', '听到他的话,我听见人群中一阵倒抽气声。', 'Cherishing Friendship', 14, 0, 'senior', 'wordlist', 'elective3', 'U2', 'hear a gasp', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'depth', 'n.', '/depθ/', '深度;(情感的)深厚', 'Not until that moment did I realise the depth of our friendship.', '直到那一刻我才意识到我们友谊的深厚。', 'Cherishing Friendship', 15, 0, 'senior', 'wordlist', 'elective3', 'U2', 'the depth of friendship', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'underestimate', 'v.', '/ˌʌndərˈestɪmeɪt/', '低估;小看', 'Never underestimate the power of a kind action.', '永远不要低估善举的力量。', 'Cherishing Friendship', 16, 0, 'senior', 'wordlist', 'elective3', 'U2', 'underestimate the power', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'crawl', 'v.', '/krɔːl/', '爬;爬行', 'He was crawling around on the ground, looking for his glasses.', '他在地上爬来爬去,找他的眼镜。', 'Cherishing Friendship', 17, 0, 'senior', 'wordlist', 'elective3', 'U2', 'crawl around', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'tear', 'n.', '/tɪə(r)/', '眼泪;泪珠', 'He tried to hold back his tears during the speech.', '演讲时他努力忍住眼泪。', 'Cherishing Friendship', 18, 0, 'senior', 'wordlist', 'elective3', 'U2', 'hold back tears', '作''眼泪''读 /tɪə(r)/;作''撕''读 /teə(r)/,此处取''眼泪''义', 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'stack', 'n.', '/stæk/', '(一)叠;(一)摞;堆', 'There was Kyle with a huge stack of books again.', '凯尔又抱着一大摞书出现了。', 'Cherishing Friendship', 19, 0, 'senior', 'wordlist', 'elective3', 'U2', 'a stack of books', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'pile', 'n.', '/paɪl/', '(一)堆;大量', 'Another boy helped him pick up the heavy pile of books.', '另一个男孩帮他把那堆沉重的书捡起来。', 'Cherishing Friendship', 20, 0, 'senior', 'wordlist', 'elective3', 'U2', 'a pile of books', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'tough', 'adj.', '/tʌf/', '艰难的;棘手的;坚强的', 'Good friends help you through those tough moments.', '好朋友会帮你度过那些艰难的时刻。', 'Cherishing Friendship', 21, 0, 'senior', 'wordlist', 'elective3', 'U2', 'tough moments', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'bunch', 'n.', '/bʌntʃ/', '一群;一束;一串', 'A bunch of kids ran towards the new boy and knocked his books down.', '一群孩子朝那个新来的男孩跑去,把他的书撞掉了。', 'Cherishing Friendship', 22, 0, 'senior', 'wordlist', 'elective3', 'U2', 'a bunch of kids', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'knock', 'v.', '/nɒk/', '撞;敲;击', 'They knocked all his books out of his arms.', '他们把他怀里的书全都撞掉了。', 'Cherishing Friendship', 23, 0, 'senior', 'wordlist', 'elective3', 'U2', 'knock down', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'trip', 'v.', '/trɪp/', '绊;绊倒', 'The older boys tripped him so that he landed in the dirt.', '那几个大男孩把他绊倒,让他摔进了泥里。', 'Cherishing Friendship', 24, 0, 'senior', 'wordlist', 'elective3', 'U2', 'trip somebody', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'dirt', 'n.', '/dɜːt/', '泥;污物;灰尘', 'His glasses went flying when he fell into the dirt.', '他摔进泥里时,眼镜飞了出去。', 'Cherishing Friendship', 25, 0, 'senior', 'wordlist', 'elective3', 'U2', 'land in the dirt', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'loneliness', 'n.', '/ˈləʊnlinəs/', '孤独;寂寞', 'He had planned to drop out because of loneliness at the new school.', '因为在新学校的孤独,他曾打算退学。', 'Cherishing Friendship', 26, 0, 'senior', 'wordlist', 'elective3', 'U2', 'feel loneliness', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'recall', 'v.', '/rɪˈkɔːl/', '回想;回忆起', 'He could not help recalling the wonderful weekend with his new friends.', '他不禁回想起和新朋友共度的美好周末。', 'Cherishing Friendship', 27, 0, 'senior', 'wordlist', 'elective3', 'U2', 'recall the weekend', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'throat', 'n.', '/θrəʊt/', '喉咙;嗓子', 'He cleared his throat and began to speak.', '他清了清嗓子,开始讲话。', 'Cherishing Friendship', 28, 0, 'senior', 'wordlist', 'elective3', 'U2', 'clear one''s throat', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'crowd', 'n.', '/kraʊd/', '人群;观众', 'Some people always seem to stand outside, looking in at the crowd of friends.', '有些人似乎总站在外面,望着那群朋友。', 'Cherishing Friendship', 29, 0, 'senior', 'wordlist', 'elective3', 'U2', 'look in at the crowd', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'freshman', 'n.', '/ˈfreʃmən/', '(中学或大学的)新生;一年级学生', 'On that Friday, a sad freshman was carrying all his books home.', '那个星期五,一个伤心的新生抱着所有的书往家走。', 'Cherishing Friendship', 30, 0, 'senior', 'wordlist', 'elective3', 'U2', 'a sad freshman', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'locker', 'n.', '/ˈlɒkə(r)/', '储物柜;锁柜', 'He had cleaned out his locker so that he would never come back.', '他已清空了储物柜,打算再也不回来。', 'Cherishing Friendship', 31, 0, 'senior', 'wordlist', 'elective3', 'U2', 'clean out a locker', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'drop out', 'phr.', '/ˌdrɒp ˈaʊt/', '退学;退出', 'Loneliness had almost made Kyle drop out of school.', '孤独差点让凯尔退学。', 'Cherishing Friendship', 32, 0, 'senior', 'wordlist', 'elective3', 'U2', 'drop out of school', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'hang out', 'phr.', '/ˌhæŋ ˈaʊt/', '一起消磨时光;闲逛', 'The two boys hung out together all that weekend.', '那个周末两个男孩一直在一起玩。', 'Cherishing Friendship', 33, 0, 'senior', 'wordlist', 'elective3', 'U2', 'hang out with friends', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'pneumonia', 'n.', '/njuːˈməʊniə/', '肺炎', 'That winter, pneumonia visited the village and touched Johnsy.', '那年冬天,肺炎袭击了村子,琼西也被感染了。', 'Cherishing Friendship', 34, 0, 'senior', 'wordlist', 'elective3', 'U2', 'catch pneumonia', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'painter', 'n.', '/ˈpeɪntə(r)/', '画家;油漆匠', 'Sue and Johnsy were two young painters who lived together.', '苏和琼西是两个住在一起的年轻画家。', 'Cherishing Friendship', 35, 0, 'senior', 'wordlist', 'elective3', 'U2', 'a young painter', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'masterpiece', 'n.', '/ˈmɑːstəpiːs/', '杰作;名作', 'The last leaf on the wall was Behrman''s masterpiece.', '墙上那片最后的叶子是贝尔曼的杰作。', 'Cherishing Friendship', 36, 0, 'senior', 'wordlist', 'elective3', 'U2', 'a great masterpiece', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'ivy', 'n.', '/ˈaɪvi/', '常春藤', 'Johnsy watched the ivy leaves falling outside her window.', '琼西望着窗外飘落的常春藤叶子。', 'Cherishing Friendship', 37, 0, 'senior', 'wordlist', 'elective3', 'U2', 'an ivy leaf', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'leaf', 'n.', '/liːf/', '叶子;树叶', 'She believed she would die when the last leaf fell.', '她相信最后一片叶子落下时她就会死去。', 'Cherishing Friendship', 38, 0, 'senior', 'wordlist', 'elective3', 'U2', 'the last leaf', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'storey', 'n.', '/ˈstɔːri/', '(楼房的)层;楼层', 'They lived at the top of a three-storey building.', '她们住在一栋三层楼房的顶层。', 'Cherishing Friendship', 39, 0, 'senior', 'wordlist', 'elective3', 'U2', 'a three-storey building', '英式拼 storey,美式拼 story;美音 /ˈstɔːri/', 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'bedside', 'n.', '/ˈbedsaɪd/', '床边;床头', 'Sue went quickly to the bedside of her sick friend.', '苏快步走到生病朋友的床边。', 'Cherishing Friendship', 40, 0, 'senior', 'wordlist', 'elective3', 'U2', 'go to the bedside', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'workroom', 'n.', '/ˈwɜːkruːm/', '工作室;工作间', 'After the doctor left, Sue went into the workroom to cry.', '医生走后,苏走进工作室哭了起来。', 'Cherishing Friendship', 41, 0, 'senior', 'wordlist', 'elective3', 'U2', 'into the workroom', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'hallway', 'n.', '/ˈhɔːlweɪ/', '门厅;走廊;过道', 'Sue had an excuse to go into the hallway as the doctor left.', '医生离开时,苏借故走到走廊里。', 'Cherishing Friendship', 42, 0, 'senior', 'wordlist', 'elective3', 'U2', 'go into the hallway', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'lantern', 'n.', '/ˈlæntən/', '灯笼;提灯', 'They found a lantern that Behrman had taken outside in the storm.', '他们发现了贝尔曼暴风雨中带到屋外的提灯。', 'Cherishing Friendship', 43, 0, 'senior', 'wordlist', 'elective3', 'U2', 'a lantern', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'anger', 'n.', '/ˈæŋɡə(r)/', '愤怒;怒火', 'Old Behrman shouted his anger over such a foolish idea.', '老贝尔曼对这种愚蠢的想法怒吼起来。', 'Cherishing Friendship', 44, 0, 'senior', 'wordlist', 'elective3', 'U2', 'shout in anger', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'fearfully', 'adv.', '/ˈfɪəfəli/', '害怕地;担心地', 'They looked fearfully out of the window at the old tree.', '他们担心地望着窗外那棵老树。', 'Cherishing Friendship', 45, 0, 'senior', 'wordlist', 'elective3', 'U2', 'look fearfully', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'recover', 'v.', '/rɪˈkʌvə(r)/', '康复;恢复', 'With good care, Johnsy slowly began to recover.', '在悉心照料下,琼西慢慢开始康复。', 'Cherishing Friendship', 46, 0, 'senior', 'wordlist', 'elective3', 'U2', 'recover from illness', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'nursing', 'n.', '/ˈnɜːsɪŋ/', '护理;看护', 'The doctor said good nursing would help her win.', '医生说悉心护理会帮她挺过来。', 'Cherishing Friendship', 47, 0, 'senior', 'wordlist', 'elective3', 'U2', 'good nursing', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'including', 'prep.', '/ɪnˈkluːdɪŋ/', '包括;包含', 'The illness touched many people, including Johnsy.', '这场病感染了很多人,包括琼西。', 'Cherishing Friendship', 48, 0, 'senior', 'wordlist', 'elective3', 'U2', 'including Johnsy', NULL, 'sufe');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('se3u2.01', '①进行式不定式 to be doing(动作正在进行)', 'A2', 12, '上外版选择性必修第三册 U2 — 当不定式表示的动作此刻或当时正在进行时,在 seem/appear/happen/pretend 等之后用 to be doing。', 1, 'elective3', 'U2', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'sufe');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('se3u2.02', '②完成式不定式 to have done(先于谓语完成)', 'A2', 12, '上外版选择性必修第三册 U2 — 当不定式动作发生在谓语动作之前并已完成时用 to have done;常见于 be glad/proud/sorry/lucky + 不定式,或 be said/thought/known/believed to ...。', 2, 'elective3', 'U2', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'sufe');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('se3u2.03', '③被动式不定式 to be done / to have been done(主语是承受者)', 'A2', 12, '上外版选择性必修第三册 U2 — 当不定式的逻辑主语是动作的承受者时用被动式不定式;need/want/deserve/hope + to be done,或 be said/believed to have been done。', 3, 'elective3', 'U2', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'sufe');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U2' AND code='se3u2.01'), 'When I first noticed Kyle, he seemed ____ a huge stack of books across the yard.', 'to be carrying', 'to carry', 'to have carried', 'to be carried', 'A', '动作在当时正在进行,用进行式不定式 to be doing。', 2, 1, 'mcq');
