INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U2' AND code='se3u2.03'), 'Tom looks upset; I feel that something needs ____ to cheer him up.', 'to be done', 'to do', 'to be doing', 'to have done', 'A', '不定式的逻辑主语是动作的承受者,用被动式不定式 to be done。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U2' AND code='se3u2.03'), 'The injured freshman needed ____ to the school nurse at once.', 'to take', 'to be taken', 'to be taking', 'to have taken', 'B', '不定式的逻辑主语是动作的承受者,用被动式不定式 to be done。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U2' AND code='se3u2.03'), 'Kyle did not want his weakest moment ____ in front of the whole school.', 'to reveal', 'to be revealing', 'to be revealed', 'to have revealed', 'C', '不定式的逻辑主语是动作的承受者,用被动式不定式 to be done。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U2' AND code='se3u2.03'), 'Every true friendship deserves ____ with patience and real care.', 'to treat', 'to be treating', 'to have treated', 'to be treated', 'D', '不定式的逻辑主语是动作的承受者,用被动式不定式 to be done。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U2' AND code='se3u2.03'), 'The scattered books needed ____ up from the muddy ground first.', 'to be picked', 'to pick', 'to be picking', 'to have picked', 'A', '不定式的逻辑主语是动作的承受者,用被动式不定式 to be done。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U2' AND code='se3u2.03'), 'Johnsy''s cold room needed ____ warm through the long winter night.', 'to keep', 'to be kept', 'to be keeping', 'to have kept', 'B', '不定式的逻辑主语是动作的承受者,用被动式不定式 to be done。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U2' AND code='se3u2.03'), 'A real friend expects nothing ____ in return for an act of kindness.', 'to give', 'to be giving', 'to be given', 'to have given', 'C', '不定式的逻辑主语是动作的承受者,用被动式不定式 to be done。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U2' AND code='se3u2.03'), 'After the fall, the muddy books still needed ____ before class.', 'to wash', 'to be washing', 'to have washed', 'to be washed', 'D', '不定式的逻辑主语是动作的承受者,用被动式不定式 to be done。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U2' AND code='se3u2.03'), 'The thank-you letter was waiting ____ to his dearest old friend.', 'to be sent', 'to send', 'to be sending', 'to have sent', 'A', '不定式的逻辑主语是动作的承受者,用被动式不定式 to be done。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U2' AND code='se3u2.03'), 'Old quarrels between close friends often deserve ____ and forgotten.', 'to forgive', 'to be forgiven', 'to be forgiving', 'to have forgiven', 'B', '不定式的逻辑主语是动作的承受者,用被动式不定式 to be done。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U2' AND code='se3u2.03'), 'The lonely freshman badly needed ____ on that difficult first day.', 'to help', 'to be helping', 'to be helped', 'to have helped', 'C', '不定式的逻辑主语是动作的承受者,用被动式不定式 to be done。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U2' AND code='se3u2.03'), 'Every classmate hoped ____ to Kyle''s graduation party that weekend.', 'to invite', 'to be inviting', 'to have invited', 'to be invited', 'D', '不定式的逻辑主语是动作的承受者,用被动式不定式 to be done。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U2' AND code='se3u2.03'), 'After all those years, the kind boy truly deserved ____ at last.', 'to be thanked', 'to thank', 'to be thanking', 'to have thanked', 'A', '不定式的逻辑主语是动作的承受者,用被动式不定式 to be done。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U2' AND code='se3u2.03'), 'Such a moving story about friendship ought ____ to everyone.', 'to tell', 'to be told', 'to be telling', 'to have told', 'B', '不定式的逻辑主语是动作的承受者,用被动式不定式 to be done。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U2' AND code='se3u2.03'), 'The freshman''s broken glasses needed ____ before the lesson began.', 'to fix', 'to be fixing', 'to be fixed', 'to have fixed', 'C', '不定式的逻辑主语是动作的承受者,用被动式不定式 to be done。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U2' AND code='se3u2.03'), 'The last leaf on the wall is believed ____ by Behrman that very night.', 'to paint', 'to be painting', 'to have painted', 'to have been painted', 'D', '动作早已完成且主语是其承受者,用完成被动式不定式 to have been done。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U2' AND code='se3u2.03'), 'These photos of our school trip are said ____ by Danny, not by me.', 'to have been taken', 'to take', 'to be taking', 'to have taken', 'A', '动作早已完成且主语是其承受者,用完成被动式不定式 to have been done。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U2' AND code='se3u2.03'), 'This famous letter of thanks is thought ____ many years ago.', 'to write', 'to have been written', 'to be writing', 'to have written', 'B', '动作早已完成且主语是其承受者,用完成被动式不定式 to have been done。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U2' AND code='se3u2.03'), 'Johnsy''s life is believed ____ by a single painted leaf on the wall.', 'to save', 'to be saving', 'to have been saved', 'to have saved', 'C', '动作早已完成且主语是其承受者,用完成被动式不定式 to have been done。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U2' AND code='se3u2.03'), 'Kyle was the first student ____ as the graduation speaker that year.', 'to choose', 'to be choosing', 'to have chosen', 'to be chosen', 'D', '不定式的逻辑主语是动作的承受者,用被动式不定式 to be done。', 2, 20, 'mcq');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (12, 'A Small Gesture', 'On a Friday afternoon, a sad freshman was carrying all his books home from his new school. A bunch of older kids ran towards him, knocked the books out of his arms and tripped him, so that he landed in the dirt. His glasses went flying. While he was crawling around looking for them, another boy stopped, handed him the glasses and helped him pick up the heavy pile. They found they lived near each other and hung out all that weekend. Over the next four years they became best friends. On graduation day, the freshman, now a popular student named Kyle, was chosen to give the speech. To everyone''s surprise, he told the story of that first afternoon. He had once planned to drop out because of loneliness, but one small act of kindness had changed his mind. With one small gesture, he said, you can truly change a person''s life.', '记叙·一个小举动改变一生', 152, '[{"q":"What happened to the freshman on that Friday afternoon?","answer":"A","options":["A group of older students knocked his books down and tripped him.","He won a prize in a school football match.","He gave a speech in front of the whole school.","He moved to a brand-new town with his family."],"explanation":"原文 ''knocked the books out of his arms and tripped him'' 的转述,其余在文中没有发生。"},{"q":"How did the two boys end up becoming friends?","answer":"B","options":["They were placed in the same sports team by a teacher.","They realised they lived nearby and spent the weekend together.","Their parents had been close friends for years.","They met again at the graduation ceremony."],"explanation":"原文 ''they lived near each other and hung out all that weekend'' 的概括。"},{"q":"What surprising thing did Kyle share in his speech?","answer":"A","options":["That he had once meant to leave school, but a kind act stopped him.","That he had secretly disliked his best friend.","That he wanted to study abroad after graduation.","That he had written the speech in a single night."],"explanation":"末段 ''He had once planned to drop out… one small act of kindness had changed his mind'' 的转述。"}]'::jsonb, '[{"word":"freshman","cn":"新生"},{"word":"gesture","cn":"举动"},{"word":"drop out","cn":"退学"}]'::jsonb, 2, 'elective3', 'U2', 'sufe');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (12, 'The Last Leaf', 'Sue and Johnsy were two young painters who shared a small flat in the city. One cold winter, Johnsy fell ill with pneumonia and lay weakly in her bed. Losing all hope, she decided that she would die when the last ivy leaf fell from the old tree outside her window. No matter what Sue said, Johnsy kept counting the falling leaves. Downstairs lived Behrman, an old painter who had never finished a great work. When Sue told him about Johnsy''s strange idea, he grew angry. That stormy night, after heavy rain and wild wind, one single leaf still held on to the wall. Day after day it refused to fall, and slowly Johnsy felt ashamed of wanting to die. She began to eat and soon started to recover. Later Sue learned the truth: Behrman had gone out and painted that last leaf on the wall during the storm. He caught pneumonia in the freezing rain and died, but his small masterpiece had saved his friend''s life.', '记叙·欧·亨利《最后一片叶子》改写', 167, '[{"q":"Why did Johnsy believe she was going to die?","answer":"B","options":["The doctor had told her there was no chance left.","She thought her life would end once the final leaf dropped.","She had quarrelled badly with her friend Sue.","She was too poor to buy any medicine."],"explanation":"原文 ''she would die when the last ivy leaf fell'' 的转述。"},{"q":"What made Johnsy change her mind and want to live?","answer":"C","options":["Sue promised to take her on a long holiday.","The doctor gave her a brand-new medicine.","The leaf that never fell made her ashamed of giving up.","Her family came to visit her every day."],"explanation":"原文 ''it refused to fall, and slowly Johnsy felt ashamed of wanting to die'' 的概括。"},{"q":"What was the truth about the last leaf?","answer":"D","options":["It was the only real leaf strong enough to survive.","Sue had tied it to the branch with a thread.","Johnsy had imagined it in her illness.","Old Behrman had secretly painted the leaf there one stormy night."],"explanation":"末段 ''Behrman had gone out and painted that last leaf on the wall'' 的转述。"}]'::jsonb, '[{"word":"pneumonia","cn":"肺炎"},{"word":"ivy","cn":"常春藤"},{"word":"masterpiece","cn":"杰作"}]'::jsonb, 2, 'elective3', 'U2', 'sufe');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (12, 'Friends Are Good for You', 'Most people know that good friends make life happier, but few realise that friendship is also good for the body. A friend is someone you trust and with whom you share a deep level of understanding. Recent studies suggest that having close friends can have a powerful effect on your physical health. In fact, a lack of close friendship may be as harmful as smoking or drinking too much. Along with regular exercise, keeping strong friendships can even add several years to a person''s life. Friends also reduce our stress and cheer us up when we are feeling low. However, keeping old friendships alive often takes more time and effort than making new ones. You need to be there for your friends whenever they need you. If you always do this, the friendship can last for a long time, even when you are unable to meet very often.', '说明·友谊有益身心健康', 148, '[{"q":"What surprising point does the passage make about friendship?","answer":"A","options":["It can be good for your physical health, not just your mood.","It always costs a lot of money to keep.","It is only useful when you are young.","It matters less than regular exercise."],"explanation":"原文 ''friendship is also good for the body… powerful effect on your physical health'' 的转述。"},{"q":"How harmful can a lack of close friends be, according to the text?","answer":"B","options":["It has no real effect on health.","It can be as harmful to the body as heavy smoking.","It only makes people feel a little bored.","It can be fixed by sleeping more."],"explanation":"原文 ''as harmful as smoking or drinking too much'' 的转述。"},{"q":"What does the writer say about keeping old friendships?","answer":"C","options":["They look after themselves with no effort.","They are easier to keep than to start.","They need time and effort, and being there when friends need you.","They should end once friends move away."],"explanation":"后段 ''takes more time and effort… be there for your friends whenever they need you'' 的概括。"}]'::jsonb, '[{"word":"stress","cn":"压力"},{"word":"effort","cn":"努力"}]'::jsonb, 2, 'elective3', 'U2', 'sufe');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (12, 'International Friendship Day', 'Friendship Day is a special time set aside to celebrate the people we care about. The idea was first created by the greeting-card industry back in the 1920s, when companies hoped that people would send cards to their friends. The day slowly grew popular in many parts of the world. In 2011, the United Nations declared the thirtieth of July as the official International Friendship Day. Its aim is to encourage governments, schools and groups to hold events that build understanding and respect between people of different backgrounds. Interestingly, the date is not the same everywhere; many countries still celebrate it on other days of the year. On this day, people send warm messages, give small gifts, or simply spend time together. Whatever the date may be, the meaning stays the same: to remind us how much our friends are needed and loved.', '说明·国际友谊日的由来', 143, '[{"q":"Who first came up with the idea of Friendship Day?","answer":"D","options":["The United Nations in 2011.","A group of school teachers.","Famous writers of the past.","Greeting-card companies in the 1920s."],"explanation":"原文 ''first created by the greeting-card industry back in the 1920s'' 的转述。"},{"q":"What is the main aim of International Friendship Day?","answer":"A","options":["To build understanding and respect among different people.","To help card companies sell more products.","To make everyone celebrate on the very same day.","To replace all other national holidays."],"explanation":"原文 ''build understanding and respect between people of different backgrounds'' 的转述。"},{"q":"What does the text say about the date of the celebration?","answer":"B","options":["Every country celebrates on the thirtieth of July.","Different countries may celebrate it on different days.","It changes from year to year in each country.","No country celebrates it any more."],"explanation":"原文 ''the date is not the same everywhere… on other days of the year'' 的转述。"}]'::jsonb, '[{"word":"declare","cn":"宣布"},{"word":"background","cn":"背景"}]'::jsonb, 2, 'elective3', 'U2', 'sufe');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (12, 'What Makes a True Friend', 'People have always tried to describe what makes a friend truly special. One famous saying tells us that a real friend is the one who walks in just as the rest of the world walks out. Another reminds us that a friend in need is a friend indeed, which means that hard times show us who our true friends really are. Good friends do much more than share our happy moments. They help us find the important things we have lost, such as our smile, our hope and our courage. A true friend is also like a clear mirror, showing us honestly who we really are. None of these old ideas is about money or expensive gifts. They all point to the same simple truth: real friendship is shown through kindness, honesty and standing by someone when life gets hard.', '议论·真朋友的价值', 140, '[{"q":"What does the saying ''a friend in need is a friend indeed'' mean here?","answer":"C","options":["Friends should always need each other.","You should only help rich friends.","Hard times reveal who your true friends are.","A real friend never asks for help."],"explanation":"原文 ''hard times show us who our true friends really are'' 的转述。"},{"q":"Besides sharing happy moments, what do good friends do?","answer":"D","options":["They give each other costly presents.","They keep our secrets from everyone.","They compete to be the most popular.","They help us find lost things like our hope and courage."],"explanation":"原文 ''help us find the important things we have lost, such as our smile, our hope and our courage'' 的转述。"},{"q":"What common truth do all these sayings point to?","answer":"A","options":["Real friendship shows in kindness, honesty and loyalty.","True friendship depends on wealth.","Friends should look exactly alike.","Old sayings are no longer useful today."],"explanation":"末句 ''real friendship is shown through kindness, honesty and standing by someone'' 的转述。"}]'::jsonb, '[{"word":"indeed","cn":"确实"},{"word":"honesty","cn":"诚实"}]'::jsonb, 2, 'elective3', 'U2', 'sufe');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (12, 'A Friend in Need', 'When Lily moved to a new town, she was shy and ate lunch alone every day. A girl named Mei noticed her sitting by herself and decided to do something about it. Instead of just feeling sorry for her, Mei sat down beside her and started a friendly chat. At first Lily said very little, but Mei kept coming back, day after day. She shared her snacks, lent Lily her notes and slowly introduced her to other classmates. Before long, Lily began to smile again and joined in their games at break. Months later, when Mei was ill and missed school for a whole week, it was Lily who brought her the homework and cheered her up. Neither girl had done anything grand, yet their small acts of care had grown into a deep friendship. Sometimes, helping a lonely person is as easy as choosing not to look away.', '记叙·雪中送炭的友谊', 149, '[{"q":"What did Mei do when she noticed Lily eating alone?","answer":"B","options":["She told a teacher to move Lily''s seat.","She sat beside Lily and began a friendly chat.","She quietly felt sorry but said nothing.","She asked Lily to leave the lunchroom."],"explanation":"原文 ''Mei sat down beside her and started a friendly chat'' 的转述。"},{"q":"How did Lily repay Mei''s kindness later on?","answer":"C","options":["She bought Mei an expensive present.","She introduced Mei to a new school.","Lily took her schoolwork to her and lifted her spirits while she was ill.","She wrote a story about their town."],"explanation":"原文 ''it was Lily who brought her the homework and cheered her up'' 的转述。"},{"q":"What lesson does the last sentence suggest?","answer":"D","options":["Only big actions can build friendship.","Lonely people prefer to be left alone.","New towns are always unfriendly places.","Helping a lonely person can be as simple as not looking away."],"explanation":"末句 ''helping a lonely person is as easy as choosing not to look away'' 的转述。"}]'::jsonb, '[{"word":"shy","cn":"害羞的"},{"word":"lend","cn":"借出"}]'::jsonb, 2, 'elective3', 'U2', 'sufe');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (12, 'elective3', 'U2', 'A New Student''s First Week', 'Moving to a new school can feel very lonely. On my first (1)____, I knew nobody and ate lunch all by myself. A boy named Sam (2)____ that I looked sad and came over to sit beside me. He had such a warm (3)____ that we were soon chatting like old friends. He (4)____ his snacks with me and showed me around the building. By the end of the (5)____, I no longer felt like a stranger. Sam even (6)____ me to his other classmates, who were all very (7)____ to me. That small act of (8)____ completely changed my week. Now I always try to (9)____ new students, because I still remember how much a single friendly (10)____ can mean.', 121, 2, '[{"q":"1","answer":"A","options":["day","trip","exam","party"],"explanation":"first day 第一天,与下文''吃午饭''对应。"},{"q":"2","answer":"B","options":["sold","noticed","lost","broke"],"explanation":"noticed that I looked sad 注意到我看起来难过。"},{"q":"3","answer":"C","options":["price","noise","smile","coin"],"explanation":"a warm smile 温暖的微笑。"},{"q":"4","answer":"D","options":["threw","hid","sold","shared"],"explanation":"shared his snacks with me 和我分享零食。"},{"q":"5","answer":"A","options":["week","metre","coin","second"],"explanation":"by the end of the week 到这周结束时。"},{"q":"6","answer":"B","options":["refused","introduced","dropped","sold"],"explanation":"introduced me to his classmates 把我介绍给同学。"},{"q":"7","answer":"C","options":["angry","asleep","kind","afraid"],"explanation":"very kind to me 对我很友善。"},{"q":"8","answer":"D","options":["anger","noise","dust","kindness"],"explanation":"an act of kindness 善举。"},{"q":"9","answer":"A","options":["welcome","ignore","blame","push"],"explanation":"welcome new students 欢迎新同学。"},{"q":"10","answer":"B","options":["storm","gesture","price","mistake"],"explanation":"a friendly gesture 友好的举动。"}]'::jsonb, 1, 'sufe');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (12, 'elective3', 'U2', 'A Thank-You Letter', 'Dear Anna, I am writing this letter to say a big thank-you. When I first arrived, I was a (1)____ student who knew no one at all. You were the first person to show me real (2)____. Whenever I felt down, you always (3)____ me, and you never (4)____ how much that meant to me. I still remember the day you (5)____ my heavy bags and walked me home in the rain. Your (6)____ has made my whole year so much (7)____. A good friend like you is really hard to (8)____. I feel truly (9)____ to have met you. Thank you for everything, and I hope our friendship will last for many (10)____. Your friend, Lily.', 117, 2, '[{"q":"1","answer":"C","options":["rich","tall","new","busy"],"explanation":"a new student 一个新生。"},{"q":"2","answer":"D","options":["anger","noise","dirt","kindness"],"explanation":"real kindness 真正的善意。"},{"q":"3","answer":"A","options":["helped","blamed","left","sold"],"explanation":"you always helped me 你总是帮我。"},{"q":"4","answer":"B","options":["enjoyed","underestimated","opened","counted"],"explanation":"never underestimated 从不低估。"},{"q":"5","answer":"C","options":["dropped","sold","carried","lost"],"explanation":"carried my heavy bags 帮我提沉重的包。"},{"q":"6","answer":"D","options":["weather","price","noise","friendship"],"explanation":"Your friendship 你的友谊。"},{"q":"7","answer":"A","options":["brighter","colder","darker","emptier"],"explanation":"so much brighter 美好得多。"},{"q":"8","answer":"B","options":["throw","find","sell","spend"],"explanation":"hard to find 很难找到。"},{"q":"9","answer":"C","options":["angry","bored","grateful","sorry"],"explanation":"truly grateful 真心感激。"},{"q":"10","answer":"D","options":["metres","coins","seconds","years"],"explanation":"many years 许多年。"}]'::jsonb, 2, 'sufe');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (12, 'elective3', 'U2', 'How Friends Help Us Grow', 'Good friends do much more than keep us company. They help us (1)____ into better people. When I lost my (2)____ before a big exam, my friends cheered me up and told me not to give (3)____. Their kind words gave me back my (4)____. A true friend is also honest, like a clear (5)____ that shows you who you really are. Sometimes a friend will gently tell you a hard (6)____ that others are afraid to mention. This kind of honesty helps us (7)____ our mistakes. Of course, friendship works both (8)____. We must also be ready to (9)____ our friends when they are in trouble. In this way, we grow (10)____ together, year after year.', 117, 2, '[{"q":"1","answer":"A","options":["grow","fall","sell","lose"],"explanation":"grow into better people 成长为更好的人。"},{"q":"2","answer":"B","options":["coin","courage","map","key"],"explanation":"lost my courage 失去勇气。"},{"q":"3","answer":"C","options":["off","away","up","down"],"explanation":"give up 放弃。"},{"q":"4","answer":"D","options":["dust","noise","price","hope"],"explanation":"gave me back my hope 让我重拾希望。"},{"q":"5","answer":"A","options":["mirror","window","door","wall"],"explanation":"a clear mirror 一面清晰的镜子。"},{"q":"6","answer":"B","options":["song","truth","price","game"],"explanation":"a hard truth 一个难以接受的真相。"},{"q":"7","answer":"C","options":["hide","sell","fix","throw"],"explanation":"fix our mistakes 改正错误。"},{"q":"8","answer":"D","options":["days","prices","coins","ways"],"explanation":"both ways 双向的。"},{"q":"9","answer":"A","options":["support","blame","ignore","leave"],"explanation":"support our friends 支持朋友。"},{"q":"10","answer":"B","options":["weaker","stronger","poorer","shorter"],"explanation":"grow stronger together 一起变得更坚强。"}]'::jsonb, 3, 'sufe');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (12, 'elective3', 'U2', 'A Rainy Day Turned Bright', 'It was pouring with rain, and I had forgotten my (1)____. Standing at the school gate, I watched everyone hurry home and felt quite (2)____. Just then my classmate Ben (3)____ over and offered to share his umbrella. We (4)____ home together, laughing as we jumped over the (5)____ in the road. On the way, he told me a funny (6)____ that made me forget the bad weather. By the time we reached my house, I was no longer (7)____. Such a small (8)____ of kindness completely changed my afternoon. Ben did not have to (9)____ me, but he chose to. That rainy day taught me how a good friend can turn even the worst day into a (10)____ one.', 120, 2, '[{"q":"1","answer":"C","options":["pencil","ticket","umbrella","coin"],"explanation":"forgotten my umbrella 忘带伞。"},{"q":"2","answer":"D","options":["rich","tall","asleep","alone"],"explanation":"felt quite alone 感到很孤单。"},{"q":"3","answer":"A","options":["came","sold","lost","threw"],"explanation":"came over 走过来。"},{"q":"4","answer":"B","options":["sold","walked","threw","lost"],"explanation":"walked home together 一起走回家。"},{"q":"5","answer":"C","options":["books","coins","pools","walls"],"explanation":"jumped over the pools 跳过水洼。"},{"q":"6","answer":"D","options":["price","noise","wall","story"],"explanation":"a funny story 一个有趣的故事。"},{"q":"7","answer":"A","options":["sad","glad","rich","asleep"],"explanation":"no longer sad 不再难过。"},{"q":"8","answer":"B","options":["price","act","noise","coin"],"explanation":"a small act of kindness 一个小小的善举。"},{"q":"9","answer":"C","options":["sleep","sell","help","hide"],"explanation":"did not have to help me 本不必帮我。"},{"q":"10","answer":"D","options":["dark","cold","empty","bright"],"explanation":"a bright one 美好的一天。"}]'::jsonb, 4, 'sufe');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (12, 'elective3', 'U2', 'Keeping Old Friends Close', 'Making new friends is exciting, but keeping old (1)____ is just as important. As we grow up, our busy lives can slowly (2)____ us apart. That is why we must put in real (3)____ to stay close. A short message or a quick (4)____ can remind an old friend that you still (5)____. Whenever my best friend has a problem, I try to be (6)____ for her, even though we live far apart. Last month I travelled for hours just to (7)____ her birthday with her. She was so (8)____ that I came all that way. Old friendships are like old trees: they need time and care to stay (9)____. If we look after them well, they can last a (10)____.', 121, 2, '[{"q":"1","answer":"A","options":["friends","coins","books","walls"],"explanation":"old friends 老朋友。"},{"q":"2","answer":"B","options":["sell","drive","throw","lose"],"explanation":"drive us apart 使我们疏远。"},{"q":"3","answer":"C","options":["price","noise","effort","dust"],"explanation":"real effort 真正的努力。"},{"q":"4","answer":"D","options":["wall","coin","storm","call"],"explanation":"a quick call 一个简短的电话。"},{"q":"5","answer":"A","options":["care","sell","lose","hide"],"explanation":"you still care 你仍然在乎。"},{"q":"6","answer":"B","options":["rich","there","tall","asleep"],"explanation":"be there for her 在她身边支持她。"},{"q":"7","answer":"C","options":["sell","drop","share","throw"],"explanation":"share her birthday 一起度过她的生日。"},{"q":"8","answer":"D","options":["angry","bored","tired","happy"],"explanation":"so happy that I came 因我赶来而高兴。"},{"q":"9","answer":"A","options":["strong","weak","poor","short"],"explanation":"stay strong 保持牢固。"},{"q":"10","answer":"B","options":["second","lifetime","metre","coin"],"explanation":"last a lifetime 持续一生。"}]'::jsonb, 5, 'sufe');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (12, 'elective3', 'U2', 'The Power of a Kind Word', 'We often (1)____ how much a single kind word can do. One morning a new boy in our class looked nervous and (2)____. I simply smiled and said, "Welcome — sit with us." His worried face lit up at (3)____. From that day on, he was no longer (4)____, and he soon became one of my closest (5)____. A small (6)____ costs nothing, yet it can change someone''s whole day. Kind words can give a worried person back his (7)____ and help him feel that he (8)____ here. We should never be too busy to (9)____ others. After all, the friendships that matter most often begin with one (10)____ act of kindness.', 112, 2, '[{"q":"1","answer":"C","options":["enjoy","count","underestimate","open"],"explanation":"often underestimate 常常低估。"},{"q":"2","answer":"D","options":["rich","tall","busy","alone"],"explanation":"nervous and alone 紧张又孤单。"},{"q":"3","answer":"A","options":["once","wall","coin","storm"],"explanation":"lit up at once 立刻亮了起来。"},{"q":"4","answer":"B","options":["happy","lonely","rich","tall"],"explanation":"no longer lonely 不再孤单。"},{"q":"5","answer":"C","options":["coins","books","friends","walls"],"explanation":"closest friends 最亲密的朋友。"},{"q":"6","answer":"D","options":["price","noise","dust","gesture"],"explanation":"a small gesture 一个小举动。"},{"q":"7","answer":"A","options":["confidence","coin","map","key"],"explanation":"back his confidence 重拾信心。"},{"q":"8","answer":"B","options":["sells","belongs","loses","hides"],"explanation":"feel that he belongs 感到自己属于这里。"},{"q":"9","answer":"C","options":["sell","throw","help","drop"],"explanation":"too busy to help others 忙得顾不上帮别人。"},{"q":"10","answer":"D","options":["angry","empty","cold","simple"],"explanation":"one simple act 一个简单的举动。"}]'::jsonb, 6, 'sufe');
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (12, 'U2 听力·对话 Welcoming a New Classmate', '上外版选择性必修第三册 U2 · dialogue', 3, 'A: Did you hear that a new student is joining our class tomorrow?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (12, 'U2 听力·短文 A Tip for Making Friends', '上外版选择性必修第三册 U2 · passage', 2, 'Here is a simple tip for making new friends.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (12, 'U2 听力·对话 An Interview on Friendship', '上外版选择性必修第三册 U2 · dialogue', 3, 'A: What does true friendship really mean to you?
